<?php require __DIR__.'/../includes/core.php';require_login(['admin']);$sections=all('SELECT * FROM school_sections ORDER BY name');if(isset($_GET['template'])){header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="bgb_teacher_import_template.csv"');$f=fopen('php://output','w');fputcsv($f,['name','phone','role','gender','school_section','classes','subjects','staff_id','temporary_password']);fputcsv($f,['Sample Teacher','08012345678','teacher','Female','Primary','Primary 5','Mathematics','BGB001','ChangeMe2026!']);exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='add'){$name=trim($_POST['name']);$tel=phone($_POST['phone']);$role=$_POST['role']??'teacher';if(!in_array($role,['teacher','supervisor','management','admin'],true)||!preg_match('/^0[0-9]{10}$/',$tel)||strlen($_POST['password']??'')<10||strlen($name)<3)throw new Exception('Check name, 11-digit phone and temporary password (10+ characters).');sql('INSERT INTO users(name,phone,password_hash,role,gender,section_id,classes,subjects,staff_id) VALUES (?,?,?,?,?,?,?,?,?)',[$name,$tel,password_hash($_POST['password'],PASSWORD_DEFAULT),$role,$_POST['gender']??'',$_POST['section_id']?:null,$_POST['classes']??'',$_POST['subjects']??'',$_POST['staff_id']??'']);audit('user_created',$tel);flash('Staff member registered.');}elseif(($_POST['action']??'')==='edit'){
$id=(int)($_POST['id']??0);$existing=one('SELECT id,role FROM users WHERE id=?',[$id]);if(!$existing)throw new Exception('Staff account not found.');
$name=trim((string)($_POST['name']??''));$tel=phone($_POST['phone']??'');$role=(string)($_POST['role']??'teacher');$section=(int)($_POST['section_id']??0);
if(strlen($name)<3||!preg_match('/^0[0-9]{10}$/',$tel)||!in_array($role,['teacher','supervisor','management','admin'],true))throw new Exception('Check name, phone and role.');
if($id==me()['id']&&$role!=='admin')throw new Exception('You cannot remove your own administrator role.');
if($section&&!one('SELECT id FROM school_sections WHERE id=?',[$section]))throw new Exception('Invalid school section.');
sql('UPDATE users SET name=?,phone=?,role=?,gender=?,section_id=?,classes=?,subjects=?,staff_id=? WHERE id=?',[$name,$tel,$role,$_POST['gender']??'',($section?:null),trim($_POST['classes']??''),trim($_POST['subjects']??''),trim($_POST['staff_id']??''),$id]);
if($id==me()['id']){$_SESSION['user']['name']=$name;$_SESSION['user']['role']=$role;}
audit('staff_details_updated',(string)$id);flash('Staff details updated.');
}elseif(($_POST['action']??'')==='reset_password'){
$id=(int)($_POST['id']??0);$new=(string)($_POST['new_password']??'');if(!one('SELECT id FROM users WHERE id=?',[$id]))throw new Exception('Staff account not found.');
if(strlen($new)<10)throw new Exception('New password must contain at least 10 characters.');
if($id==me()['id'])throw new Exception('Use the Password page to change your own password.');
sql('UPDATE users SET password_hash=?,must_change_password=1 WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$id]);
audit('staff_password_reset',(string)$id);flash('Password reset. The staff member must change it at next login.');
}elseif(($_POST['action']??'')==='toggle'){$id=(int)$_POST['id'];if($id==me()['id'])throw new Exception('You cannot deactivate your own account.');sql('UPDATE users SET is_active=1-is_active WHERE id=?',[$id]);audit('user_status_changed',(string)$id);flash('Account status changed.');}elseif(($_POST['action']??'')==='import'){if(!is_uploaded_file($_FILES['csv']['tmp_name']??''))throw new Exception('Select a CSV file.');$fp=fopen($_FILES['csv']['tmp_name'],'r');$head=array_map(fn($x)=>strtolower(trim((string)$x)),fgetcsv($fp)?:[]);$required=['name','phone','role','gender','school_section','classes','subjects','staff_id','temporary_password'];if(array_diff($required,$head))throw new Exception('CSV headings do not match the template.');$inserted=0;$errors=[];$row=1;while(($vals=fgetcsv($fp))!==false){$row++;if(!array_filter($vals))continue;$d=array_combine($head,array_pad($vals,count($head),''));$tel=phone($d['phone']);$role=$d['role']?:'teacher';if(!preg_match('/^0[0-9]{10}$/',$tel)||strlen($d['temporary_password'])<10||!in_array($role,['teacher','supervisor','management','admin'],true)){$errors[]="Row $row: invalid phone, role or password";continue;}$sec=one('SELECT id FROM school_sections WHERE name=?',[$d['school_section']]);try{sql('INSERT INTO users(name,phone,password_hash,role,gender,section_id,classes,subjects,staff_id) VALUES (?,?,?,?,?,?,?,?,?)',[$d['name'],$tel,password_hash($d['temporary_password'],PASSWORD_DEFAULT),$role,$d['gender'],$sec['id']??null,$d['classes'],$d['subjects'],$d['staff_id']]);$inserted++;}catch(Throwable $e){$errors[]="Row $row: duplicate phone or invalid data";}}fclose($fp);audit('teacher_import',"Imported $inserted");flash("Imported $inserted accounts. ".implode('; ',array_slice($errors,0,5)), $errors?'error':'success');}go('admin/teachers.php');}catch(Throwable $e){$error=$e->getMessage();}}$users=all('SELECT u.*,s.name section_name FROM users u LEFT JOIN school_sections s ON s.id=u.section_id ORDER BY u.id DESC');ob_start();if($error)echo '<div class="alert error">'.h($error).'</div>';?><div class="card"><h2>Register staff member</h2><form method="post"><?=token()?><input type="hidden" name="action" value="add"><div class="formgrid"><div><label>Full name</label><input name="name" required></div><div><label>Phone (login)</label><input name="phone" required placeholder="08012345678"></div><div><label>Role</label><select name="role"><option>teacher</option><option>supervisor</option><option>management</option><option>admin</option></select></div><div><label>Gender</label><select name="gender"><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option></select></div><div><label>School section</label><select name="section_id"><option value="">Select</option><?php foreach($sections as $s)echo '<option value="'.h($s['id']).'">'.h($s['name']).'</option>';?></select></div><div><label>Class(es)</label><input name="classes"></div><div><label>Subject(s)</label><input name="subjects"></div><div><label>Staff ID</label><input name="staff_id"></div><div><label>Temporary password (10+ characters)</label><input name="password" minlength="10" required></div></div><p><button>Register staff</button></p></form></div><div class="card"><h2>Bulk CSV import</h2><p><a class="btn alt" href="?template=1">Download CSV template</a></p><form method="post" enctype="multipart/form-data"><?=token()?><input type="hidden" name="action" value="import"><input type="file" name="csv" accept=".csv,text/csv" required><p><button>Import teachers</button></p></form><p class="muted small">Excel can open and save this CSV template. Each imported user must change their password on first login.</p></div><?php $editId=(int)($_GET['edit']??0);$editUser=$editId?one('SELECT * FROM users WHERE id=?',[$editId]):null;if($editUser):?><div class="card" id="edit-staff"><h2>Edit staff: <?=h($editUser['name'])?></h2><form method="post"><?=token()?><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=h($editUser['id'])?>"><div class="formgrid"><div><label>Full name</label><input name="name" required value="<?=h($editUser['name'])?>"></div><div><label>Phone (login)</label><input name="phone" required value="<?=h($editUser['phone'])?>"></div><div><label>Role</label><select name="role"><?php foreach(['teacher','supervisor','management','admin'] as $role)echo '<option value="'.h($role).'" '.($editUser['role']===$role?'selected':'').'>'.h(ucfirst($role)).'</option>';?></select></div><div><label>Gender</label><select name="gender"><?php foreach([''=>'Select','Female'=>'Female','Male'=>'Male','Other'=>'Other'] as $v=>$label)echo '<option value="'.h($v).'" '.($editUser['gender']===$v?'selected':'').'>'.h($label).'</option>';?></select></div><div><label>School section</label><select name="section_id"><option value="">Select</option><?php foreach($sections as $sec)echo '<option value="'.h($sec['id']).'" '.((int)$editUser['section_id']===(int)$sec['id']?'selected':'').'>'.h($sec['name']).'</option>';?></select></div><div><label>Class(es)</label><input name="classes" value="<?=h($editUser['classes'])?>"></div><div><label>Subject(s)</label><input name="subjects" value="<?=h($editUser['subjects'])?>"></div><div><label>Staff ID</label><input name="staff_id" value="<?=h($editUser['staff_id'])?>"></div></div><p><button>Save changes</button> <a class="btn alt" href="<?=url('admin/teachers.php')?>">Cancel</a></p></form><hr><h3>Reset staff password</h3><p class="muted small">This sets a temporary password. The staff member must change it on their next login.</p><form method="post" onsubmit="return confirm('Reset this staff member’s password?')"><?=token()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="id" value="<?=h($editUser['id'])?>"><label>New temporary password (at least 10 characters)</label><input type="password" name="new_password" minlength="10" autocomplete="new-password" required><p><button>Reset password</button></p></form></div><?php endif;?><div class="card"><h2>Registered staff</h2><div class="tablewrap"><table><tr><th>Name</th><th>Phone</th><th>Role</th><th>Section</th><th>Status</th><th>Action</th></tr><?php foreach($users as $u){echo '<tr><td>'.h($u['name']).'</td><td>'.h($u['phone']).'</td><td>'.h($u['role']).'</td><td>'.h($u['section_name']).'</td><td>'.($u['is_active']?'Active':'Inactive').'</td><td>';if($u['id']!=me()['id'])echo '<form method="post">'.token().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.h($u['id']).'"><button>'.($u['is_active']?'Deactivate':'Activate').'</button></form>';echo ' <a class="btn alt" href="'.url('admin/teachers.php?edit='.$u['id'].'#edit-staff').'">Edit / Password</a>';echo '</td></tr>';}?></table></div></div><?php layout('Teacher & staff registration',ob_get_clean());